          'Heroe.',
          'Error.',
          'Sucesor.',
          'Monstruo.',
          'Kael siguio caminando sin aceptar ninguna completamente.',
          'Kael salio finalmente hacia un amanecer gris cubriendo un mundo desconocido.',
          'No habia coronas.',
          'No habia titulos.',
